 10	function subscriptionEnv(source = process.env) {
 11	  const env = { ...source };
 12	  for (const key of ['OPENAI_API_KEY', 'OPENAI_BASE_URL', 'CODEX_API_KEY', 'NODE_OPTIONS', 'NODE_PATH']) delete env[key];
 13	  env.PATH = '/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin';
 14	  // HTTP SSE exposes the service response model; exec JSONL alone does not.
 15	  env.RUST_LOG = 'codex_api::sse::responses=trace';
 16	  return env;
 17	}
