 19	function invoke(command, args, options) {
 20	  return new Promise(resolve => {
 21	    const { input, ...execOptions } = options;
 22	    let inputError = null;
 23	    const child = execFile(command, args, execOptions, (error, stdout, stderr) => resolve({ error: error || inputError, stdout, stderr }));
 24	    if (input !== undefined) {
 25	      child.stdin.on('error', error => { inputError = error; });
 26	      child.stdin.end(input);
 27	    }
 28	  });
 29	}
