 31	function parseCodexTapes(stdout, stderr, requestedModel) {
 32	  const frames = [];
 33	  const events = [];
 34	  const parseErrors = [];
 35	  for (const line of String(stdout).split('\n').filter(Boolean)) {
 36	    try {
 37	      const frame = JSON.parse(line);
 38	      if (frame && typeof frame === 'object' && !Array.isArray(frame)) frames.push(frame);
 39	      else parseErrors.push('invalid_exec_frame');
 40	    } catch { parseErrors.push('invalid_exec_jsonl'); }
 41	  }
 42	  for (const line of String(stderr).split('\n')) {
 43	    const offset = line.indexOf('SSE event: ');
 44	    if (offset < 0) continue;
 45	    const payload = line.slice(offset + 'SSE event: '.length);
 46	    if (payload === '[DONE]') continue;
 47	    try {
 48	      const event = JSON.parse(payload);
 49	      if (event && typeof event === 'object' && !Array.isArray(event)) events.push(event);
 50	      else parseErrors.push('invalid_provider_event');
 51	    } catch { parseErrors.push('invalid_provider_sse'); }
 52	  }
 53	  const observations = events.filter(event => event.response || event.type === 'response.completed').map(event => ({
 54	    event: event.type, responseId: event.response?.id, model: event.response?.model || null,
 55	  }));
 56	  const completed = events.filter(event => event.type === 'response.completed');
 57	  for (const event of completed) {
 58	    if (!event.response || typeof event.response.model !== 'string') parseErrors.push('invalid_provider_completion');
 59	  }
 60	  const models = [...new Set(observations.map(item => item.model).filter(Boolean))];
 61	  const identityVerified = completed.length > 0 && observations.every(item => item.model === requestedModel);
 62	  const calls = events.filter(event => event.type === 'response.output_item.done'
 63	    && ['function_call', 'custom_tool_call'].includes(event.item && event.item.type))
 64	    .map(event => ({ id: event.item.call_id, name: event.item.name,
 65	      arguments: event.item.arguments === undefined ? event.item.input : event.item.arguments,
 66	      status: 'requested' }));
 67	  const catalogs = events.filter(event => Array.isArray(event.response?.tools));
 68	  const names = (tool, prefix = '') => {
 69	    const pending = [{ tool, prefix }], found = [];
 70	    while (pending.length) {
 71	      const entry = pending.pop(), value = entry.tool;
 72	      if (!value || typeof value !== 'object' || typeof value.name !== 'string') {
 73	        parseErrors.push('[REDACTED]');
 74	      } else if (value.type !== 'namespace') {
 75	        found.push(entry.prefix + value.name);
 76	      } else if (!Array.isArray(value.tools)) {
 77	        parseErrors.push('invalid_provider_tool_namespace');
 78	      } else {
 79	        for (let index = value.tools.length - 1; index >= 0; index -= 1) {
 80	          pending.push({ tool: value.tools[index], prefix: entry.prefix + value.name + '.' });
 81	        }
 82	      }
 83	    }
 84	    return found;
 85	  };
 86	  const available = [...new Set(catalogs.flatMap(event => event.response.tools.flatMap(tool => names(tool))))];
 87	  const tools = {
 88	    enabled: true,
 89	    available,
 90	    availability_status: catalogs.length ? 'provider_response_catalog' : '[REDACTED]',
 91	    calls,
 92	    total: calls.length,
 93	    succeeded: null,
 94	    failed: null,
 95	    outcome_status: 'see_exec_events_and_raw_tapes',
 96	    execution_events: frames.filter(frame => frame.item && frame.item.type !== 'agent_message'),
 97	  };
 98	  const answer = frames.filter(frame => frame.type === 'item.completed' && frame.item && frame.item.type === 'agent_message')
 99	    .map(frame => frame.item.text).at(-1) || '';
100	  const complete = frames.some(frame => frame.type === 'turn.completed');
101	  return { frames, events, parseErrors, observations, models, completed, identityVerified, tools, answer, complete };
102	}
