104	class CodexChallengerClient {
105	  constructor(options) {
106	    Object.assign(this, options);
107	    this.providerName = 'codex-subscription';
108	    this.requestCount = 0;
109	    this.invoke = options.invoke || invoke;
110	    this.initialized = false;
