113	  async initialize() {
114	    if (this.initialized) return;
115	    const realpath = fs.realpathSync(CODEX_LAUNCHER);
116	    const packagePath = path.resolve(path.dirname(realpath), '../package.json');
117	    const packageInfo = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
118	    const version = await this.invoke(CODEX_LAUNCHER, ['--version'], this.execOptions());
119	    const auth = await this.invoke(CODEX_LAUNCHER, ['login', 'status'], this.execOptions());
120	    this.executableTrust = {
121	      trusted: packageInfo.name === '@openai/codex' && !version.error
122	        && String(version.stdout).trim() === `codex-cli ${packageInfo.version}`,
123	      realpath, version: String(version.stdout).trim(), package: packageInfo.name,
124	    };
125	    this.authStatus = { authenticated: !auth.error && /Logged in using ChatGPT/.test(String(auth.stdout) + String(auth.stderr)), method: 'chatgpt_subscription' };
126	    this.initialization = { version, auth };
127	    this.initialized = true;
128	  }
129	
130	  execOptions() {
131	    return { cwd: this.repoRoot, env: subscriptionEnv(), timeout: this.requestTimeoutMs,
132	      maxBuffer: 64 * 1024 * 1024, encoding: 'utf8' };
133	  }
134	
135	  async generateResponseWithMetadata(prompt) {
136	    await this.initialize();
137	    const started = Date.now();
138	    const args = ['exec', '--ignore-user-config', '--ephemeral', '--skip-git-repo-check',
139	      '--sandbox', 'read-only', '--json', '--model', this.model, '--cd', this.repoRoot,
140	      '-c', 'approval_policy="never"', '-c', 'forced_login_method="chatgpt"',
141	      '-c', 'model_provider="panel-subscription"',
142	      '-c', 'model_providers.panel-subscription.name="ChatGPT subscription"',
143	      '-c', `model_providers.panel-subscription.base_url="${SUBSCRIPTION_ENDPOINT}"`,
144	      '-c', 'model_providers.panel-subscription.wire_api="responses"',
145	      '-c', 'model_providers.panel-subscription.requires_openai_auth=true',
146	      '-c', 'model_providers.panel-subscription.supports_websockets=false',
147	      '-c', `developer_instructions=${JSON.stringify(this.systemPrompt.replace('You do not have repo tools in this review pass.',
148	        'Use the available tools for read-only evidence inspection in the supplied working directory; it is the selected source snapshot when a review ref is pinned. Do not substitute the parent checkout. Do not edit files, call other reviewers, or change runtime state.'))}`,
149	      '-'];
150	    const result = await this.invoke(CODEX_LAUNCHER, args, { ...this.execOptions(), input: prompt });
151	    this.requestCount += 1;
152	    const parsed = parseCodexTapes(result.stdout, result.stderr, this.model);
153	    const termination = result.error ? 'error' : (parsed.complete ? 'stop' : 'incomplete');
154	    const metadata = {
155	      provider: this.providerName, requestedModel: this.model,
156	      appliedModel: parsed.models.at(-1) || null, appliedModels: parsed.models,
157	      verdictModels: parsed.completed.map(event => event.response?.model ?? null),
158	      modelObservations: parsed.observations, modelTransitions: [],
159	      identityPosture: { status: parsed.identityVerified ? 'verified' : 'identity_conflict',
160	        authority: 'provider_response_sse', reason: parsed.identityVerified ? 'every_response_model_matches' : '[REDACTED]' },
161	      startedAt: new Date(started).toISOString(), finishedAt: new Date().toISOString(), latencyMs: Date.now() - started,
162	      exitCode: result.error ? result.error.code : 0, termination,
163	      stoppedBecause: result.error ? result.error.message : termination,
164	      providerError: result.error ? { name: result.error.name, message: result.error.message,
165	        code: result.error.code || null, signal: result.error.signal || null, killed: result.error.killed === true } : null,
166	      parseStatus: parsed.parseErrors.length ? 'parse_errors' : (parsed.complete ? 'complete' : 'incomplete'), parseErrors: parsed.parseErrors,
167	      initialization: this.initialization || null,
168	      usage: parsed.frames.findLast(frame => frame.type === 'turn.completed')?.usage || null,
169	      rawResponse: Buffer.from(result.stdout || ''), rawError: Buffer.from(result.stderr || ''),
170	      providerFrames: parsed.events, toolsAvailable: parsed.tools.available, tools: parsed.tools,
171	      providerErrors: parsed.frames.filter(frame => frame.type === 'error' || frame.type === 'turn.failed'),
172	      authStatus: this.authStatus, executableTrust: this.executableTrust,
173	      invocation: { executable: CODEX_LAUNCHER, args, subscriptionEndpoint: SUBSCRIPTION_ENDPOINT,
174	        configuredMaxTokens: this.maxTokens, outputTokenLimitEnforced: false },
175	    };
176	    // Preserve the answer and every diagnostic. Existing panel routing owns seat handling.
177	    return { answer: parsed.answer, metadata };
178	  }
179	}
