 24	function classifyProviderError(err) {
 25	  const message = err && err.message ? err.message : String(err);
 26	  if (/free_tier_quota_exceeded|free tier limit|insufficient balance|rate limit|requires a subscription|upgrade for access|HTTP 402|HTTP 403|HTTP 429/i.test(message)) {
 27	    return 'quota_or_billing';
 28	  }
 29	  if (/authentication_error|invalid x-api-key|HTTP 401|api key env is missing|missing/i.test(message)) {
 30	    return 'auth';
 31	  }
 32	  if (/model.*not.*found|not_found|does not exist|unsupported/i.test(message)) {
 33	    return 'model';
 34	  }
 35	  if (/timeout|ETIMEDOUT|ECONNRESET|ENOTFOUND|EAI_AGAIN/i.test(message)) {
 36	    return 'network';
 37	  }
 38	  return 'unknown';
 39	}
